<template>
 <article class="analysis-document">
  <section class="result-summary"><small>{{overview?'整体功能':'解读摘要'}}</small><p>{{result.summary}}</p></section>
  <details v-for="(section,i) in result.sections||[]" :key="i" class="analysis-section" :open="i===0"><summary><span>{{String(i+1).padStart(2,'0')}}</span>{{section.title}}</summary><div class="section-content"><p>{{section.content}}</p><div class="references"><button v-for="ref in section.refs" :key="ref.fileId+':'+ref.startLine" @click="$emit('reference',ref)">{{fileName(ref.fileId)}} · {{ref.startLine}}–{{ref.endLine}} 行</button></div></div></details>
  <details v-if="result.questions?.length" class="analysis-section"><summary>待确认事项 · {{result.questions.length}}</summary><ul><li v-for="item in result.questions" :key="item">{{item}}</li></ul></details>
  <section v-if="result.changes?.length" class="proposals"><h4>修改建议 · 待验证</h4><details v-for="(change,i) in result.changes" :key="i" class="analysis-section"><summary>{{fileName(change.fileId)}} · {{change.startLine}}–{{change.endLine}} 行</summary><p>{{change.reason}}</p><div class="change-before"><b>原始代码</b><pre>{{change.original}}</pre></div><div class="change-after"><b>建议代码</b><pre>{{change.replacement}}</pre></div><ul><li v-for="test in change.tests" :key="test">需验证：{{test}}</li></ul></details><el-checkbox :model-value="confirmedChanges" :disabled="!canInteract" @update:model-value="$emit('update:confirmedChanges',$event)">已核对修改，另存为待验证阅读稿</el-checkbox></section>
  <footer>{{result.model||'已保存结果'}} · AI解释需人工核对，未经过控制器编译或现场验证</footer>
 </article>
</template>
<script setup>
